@layer theme, base, components, utilities;

/* Shared text utilities; other components compose these classes. */

/* The fade only shows when text overflows: otherwise the scroll timeline is inactive. */

@property --truncate-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  /* Text that's never cut: a long name, email or path breaks onto the next
     line, inside a word only when there's nowhere else to break. Use this for
     anything a person needs to read in full. */
  .wrap {
    min-width: 0;
    overflow-wrap: anywhere;
    text-wrap: pretty;
  }

  /* One line, fading at the end when cut. Only for rows that must keep a
     fixed height (a virtualized table); give the full text a title too. The padding/negative margin stops
     overflow: hidden clipping descenders and accents at tight line heights. */
  .truncate {
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    padding-block: 0.2em;
    margin-block: -0.2em;
  }

  /* Several lines; set --truncate-lines (default 2). */
  .truncateLines {
    overflow: hidden;
    max-height: calc(var(--truncate-lines, 2) * 1lh);
  }

  @supports (animation-timeline: scroll()) {
    .truncate,
    .truncateLines {
      --truncate-to: right;
      animation: truncate-overflow linear both;
    }

    :is([dir="rtl"]) .truncate,
    :is([dir="rtl"]) .truncateLines {
      --truncate-to: left;
    }

    .truncate {
      mask-image: linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      animation-timeline: scroll(self inline);
    }

    .truncateLines {
      mask-image:
        linear-gradient(#000 0 0),
        linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      mask-size: 100% calc(100% - 1lh), 100% 1lh;
      mask-position: top, bottom;
      mask-repeat: no-repeat;
      animation-timeline: scroll(self block);
    }
  }

  /* Without scroll timelines, fall back to an ellipsis. */
  @supports not (animation-timeline: scroll()) {
    .truncate {
      text-overflow: ellipsis;
    }

    .truncateLines {
      display: -webkit-box;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--truncate-lines, 2);
    }
  }

  @keyframes truncate-overflow {
    from,
    to {
      --truncate-fade: 24px;
    }
  }

  /* Visually hidden, still read by screen readers. */
  .srOnly {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* Work in progress: a light band sweeps across dimmed text. --sweep-dim sets the dim. */
  .sweep {
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation: sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .sweep {
      mask-image: none;
      animation: none;
    }
  }
}

@layer theme, base, components, utilities;

/* The real label, for screen readers and find-in-page. */
.label {
  composes: srOnly from "../text/text.module.css";
}

/* Block padding keeps descenders inside the mask. */
@property --morph-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  .root {
    position: relative;
    display: inline-flex;
    white-space: pre;
  }

  .row {
    --morph-to: right;
    position: relative;
    display: inline-flex;
    padding-block: 0.3em;
    margin-block: -0.3em;
  }

  :is([dir="rtl"]) .row {
    --morph-to: left;
  }

  .row[data-morphing] {
    mask-image: linear-gradient(to var(--morph-to), #000 calc(100% - var(--morph-fade)), transparent);
  }

  /* A filter (the blur on arriving and leaving letters) paints only inside
     the element's box, and a glyph's descender hangs below a tight line box.
     The block padding grows each letter's box to hold its descenders; the
     negative margin gives the room back, so nothing moves. */
  .glyph {
    display: inline-block;
    padding-block: 0.3em;
    margin-block: -0.3em;
  }

  .ghosts {
    position: absolute;
    inset: 0;
    pointer-events: none;
  }

  /* Sits where the letter sat: the row's block padding, held as the ghost's
     own padding so its blur has room for descenders too. */
  .ghost {
    position: absolute;
    top: 0;
    padding-block: 0.3em;
  }
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import styles from "./text-morph.module.css";

type Glyph = { key: string; char: string };
type Layout = { text: string; glyphs: Glyph[]; lefts: Map<string, number>; width: number };

const segmenter =
  typeof Intl !== "undefined" && "Segmenter" in Intl
    ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
    : null;

function split(text: string) {
  return segmenter ? Array.from(segmenter.segment(text), (s) => s.segment) : Array.from(text);
}

type Word = { start: number; end: number; text: string };

function words(chars: string[]): Word[] {
  const out: Word[] = [];
  let start = -1;
  chars.forEach((c, i) => {
    const space = /\s/.test(c);
    if (!space && start === -1) start = i;
    if (space && start !== -1) {
      out.push({ start, end: i, text: chars.slice(start, i).join("").toLowerCase() });
      start = -1;
    }
  });
  if (start !== -1) out.push({ start, end: chars.length, text: chars.slice(start).join("").toLowerCase() });
  return out;
}

/** Shared start and end letters: "Copy" → "Copied" keeps "Cop". */
function edges(a: string[], b: string[]): [number, number][] {
  const pairs: [number, number][] = [];
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) pairs.push([start, start++]);
  for (let k = 1; k <= Math.min(a.length, b.length) - start && a[a.length - k] === b[b.length - k]; k++) {
    pairs.push([a.length - k, b.length - k]);
  }
  return pairs;
}

/** Keys letters, reusing old keys for shared words and gap edges so they slide. */
function toGlyphs(prev: Glyph[] | null, text: string, generation: number): Glyph[] {
  // Same keys on the server and in the browser.
  const fresh = (i: number) => `${generation}:${i}`;
  const chars = split(text);
  if (!prev) return chars.map((char, i) => ({ key: fresh(i), char }));
  const keys: (string | null)[] = chars.map(() => null);
  const old = prev.map((g) => g.char);

  // Numbers match by place value, from the right.
  if (numeric(old.join("")) && numeric(text)) {
    for (let k = 1; k <= Math.min(old.length, chars.length); k++) {
      if (old[old.length - k] === chars[chars.length - k]) keys[chars.length - k] = prev[old.length - k].key;
    }
    return chars.map((char, i) => ({ key: keys[i] ?? fresh(i), char }));
  }

  const oldWords = words(old);
  const used = new Set<number>();
  const anchors: { from: Word; to: Word }[] = [];
  for (const w of words(chars)) {
    const i = oldWords.findIndex((o, k) => !used.has(k) && o.text === w.text);
    if (i === -1) continue;
    used.add(i);
    anchors.push({ from: oldWords[i], to: w });
    for (let k = 0; k < w.end - w.start; k++) {
      if (old[oldWords[i].start + k] === chars[w.start + k]) keys[w.start + k] = prev[oldWords[i].start + k].key;
    }
  }

  const ordered = anchors.every((a, i) => i === 0 || a.from.start > anchors[i - 1].from.end);
  if (ordered) {
    const bounds = [{ from: 0, to: 0 }, ...anchors.map((a) => ({ from: a.from.end, to: a.to.end }))];
    const ends = [...anchors.map((a) => ({ from: a.from.start, to: a.to.start })), { from: old.length, to: chars.length }];
    bounds.forEach((b, g) => {
      const pairs = edges(old.slice(b.from, ends[g].from), chars.slice(b.to, ends[g].to));
      for (const [i, j] of pairs) keys[b.to + j] = prev[b.from + i].key;
    });
  }

  return chars.map((char, i) => ({ key: keys[i] ?? fresh(i), char }));
}

const NUMERIC = /^[^\p{L}]*\d[^\p{L}]*$/u;
const numeric = (text: string) => NUMERIC.test(text);

const NUMBER = /[-\u2212]?\d[\d,.]*/;

function value(text: string) {
  const match = text.match(NUMBER);
  return match ? parseFloat(match[0].replace("\u2212", "-").replace(/,/g, "")) : NaN;
}

function direction(from: string, to: string) {
  const delta = value(to) - value(from);
  return Number.isNaN(delta) ? 0 : Math.sign(delta);
}

function token(el: Element, name: string, fallback: string) {
  return getComputedStyle(el).getPropertyValue(name).trim() || fallback;
}

function ms(value: string) {
  return value.endsWith("ms") ? parseFloat(value) : parseFloat(value) * 1000;
}

function translateX(el: Element) {
  const transform = getComputedStyle(el).transform;
  return transform && transform !== "none" ? new DOMMatrixReadOnly(transform).m41 : 0;
}

function measureText(row: HTMLElement, text: string, glyphs: Glyph[]): Layout {
  const node = row.firstChild;
  const origin = row.getBoundingClientRect().left;
  const lefts = new Map<string, number>();
  let width = 0;
  if (node?.nodeType === Node.TEXT_NODE) {
    const range = document.createRange();
    let offset = 0;
    for (const g of glyphs) {
      range.setStart(node, offset);
      range.setEnd(node, (offset += g.char.length));
      const box = range.getBoundingClientRect();
      lefts.set(g.key, box.left - origin);
      width = Math.max(width, box.right - origin);
    }
  }
  return { text, glyphs, lefts, width };
}

export function TextMorph({ children, className }: { children: string; className?: string }) {
  const [shown, setShown] = useState(children);
  const [state, setState] = useState(() => ({ generation: 0, glyphs: toGlyphs(null, children, 0) }));
  if (shown !== children) {
    setShown(children);
    setState((prev) => ({ generation: prev.generation + 1, glyphs: toGlyphs(prev.glyphs, children, prev.generation + 1) }));
  }
  const { glyphs } = state;
  // Plain text until the label first changes.
  const split = state.generation > 0;
  const rowRef = useRef<HTMLSpanElement>(null);
  const ghostsRef = useRef<HTMLSpanElement>(null);
  const layout = useRef<Layout | null>(null);

  useLayoutEffect(() => {
    const row = rowRef.current;
    const ghosts = ghostsRef.current;
    if (!row || !ghosts) return;

    if (!split) {
      layout.current = measureText(row, children, glyphs);
      return;
    }

    const nodes = new Map<string, HTMLElement>();
    for (const el of row.querySelectorAll<HTMLElement>("[data-glyph]")) nodes.set(el.dataset.glyph!, el);

    const last = layout.current;
    const lefts = new Map(glyphs.map((g) => [g.key, nodes.get(g.key)!.offsetLeft]));
    const tail = nodes.get(glyphs.at(-1)?.key ?? "");
    // Fractional, like the row's own width: offsetWidth rounds, and the
    // animation would end half a pixel short and then snap.
    const width = tail ? tail.getBoundingClientRect().right - row.getBoundingClientRect().left : 0;
    layout.current = { text: children, glyphs, lefts, width };

    if (!last || last.text === children) return;
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) {
      ghosts.replaceChildren();
      return;
    }

    // The glide, not the move spring: a spring's overshoot narrows a button
    // past its new width and springs it back, which reads as the control
    // settling after the click. The glide lands once.
    const spring = token(row, "--ui-ease-glide", "cubic-bezier(0.22, 1, 0.36, 1)");
    const easeExit = token(row, "--ui-ease-exit", "cubic-bezier(0.4, 0, 1, 1)");
    const duration = ms(token(row, "--ui-dur-glide", "320ms"));
    const exit = ms(token(row, "--ui-dur-instant", "150ms"));
    // Letters arrive on the plain enter curve: a spring would bounce them
    // up and down, and vertical bounce reads as jitter in a line of text.
    const enter = token(row, "--ui-ease-enter", "cubic-bezier(0.2, 1, 0.3, 1)");

    // If a previous morph is still running, start from where it visibly is.
    const running = row.getAnimations();
    const fromWidth = running.length ? row.getBoundingClientRect().width : last.width;
    running.forEach((a) => a.cancel());
    const fade = Math.min(16, Math.abs(width - fromWidth));
    row.dataset.morphing = "";
    const grow = row.animate(
      { width: [`${fromWidth}px`, `${width}px`], ["--morph-fade" as string]: [`${fade}px`, "0px"] },
      { duration, easing: spring },
    );
    grow.finished.then(
      () => delete row.dataset.morphing,
      () => {}, // cancelled by a newer morph, which owns the flag now
    );

    const dir = direction(last.text, children) || 1;
    // A small rise with a soft blur: the change reads, the line holds still.
    const enterFrom = `translateY(${0.08 * dir}em)`;
    const leaveTo = `translateY(${-0.08 * dir}em)`;

    // Arrivals wait for leaving letters to clear.
    const current = new Set(glyphs.map((g) => g.key));
    const leaving = last.glyphs.some((g) => !current.has(g.key));
    const lead = exit * (leaving ? 0.85 : 0.4);
    // Arrivals finish with the width, never after it: each starts once the
    // leaving letters clear, a little after the one before, and is timed to
    // land on the same frame the glide does.
    const arriving = glyphs.filter((g) => !last.lefts.has(g.key)).length;
    const stagger = Math.min(15, (duration - lead - 120) / Math.max(1, arriving));
    let entering = 0;
    for (const g of glyphs) {
      const el = nodes.get(g.key)!;
      const before = last.lefts.get(g.key);
      if (before === undefined) {
        const delay = lead + entering++ * stagger;
        el.animate(
          {
            opacity: [0, 1],
            transform: [enterFrom, "none"],
            filter: ["blur(2px)", "none"],
          },
          { duration: Math.max(120, duration - delay), easing: enter, delay, fill: "backwards" },
        );
        continue;
      }
      // FLIP from where the letter is on screen now.
      const offset = before + translateX(el) - lefts.get(g.key)!;
      el.getAnimations().forEach((a) => a.cancel());
      if (Math.abs(offset) > 0.5) {
        el.animate({ transform: [`translateX(${offset}px)`, "none"] }, { duration, easing: spring });
      }
    }

    // Ghosts live in a layer React never renders into.
    const kept = new Set(glyphs.map((g) => g.key));
    for (const g of last.glyphs) {
      if (kept.has(g.key)) continue;
      const ghost = document.createElement("span");
      ghost.className = styles.ghost;
      ghost.textContent = g.char;
      ghost.style.left = `${last.lefts.get(g.key)}px`;
      ghosts.append(ghost);
      const fade = ghost.animate(
        {
          opacity: [1, 0],
          transform: ["none", leaveTo],
          filter: ["none", "blur(2px)"],
        },
        { duration: exit, easing: easeExit, fill: "forwards" },
      );
      fade.finished.then(
        () => ghost.remove(),
        () => ghost.remove(),
      );
    }
  }, [children, glyphs, split]);

  return (
    // The letter row must run in the label's own direction.
    <span className={className ? `${styles.root} ${className}` : styles.root} dir="auto">
      <span className={styles.label}>{children}</span>
      <span ref={rowRef} className={styles.row} aria-hidden="true">
        {split
          ? glyphs.map((g) => (
              <span key={g.key} data-glyph={g.key} className={styles.glyph}>
                {g.char}
              </span>
            ))
          : children}
        <span ref={ghostsRef} className={styles.ghosts} />
      </span>
    </span>
  );
}

@layer theme, base, components, utilities;

.label {
  composes: wrap from "../text/text.module.css";
}

@layer components {
  /* A label row over a control row. The control row is a control height
     (--slider-h): the whole hit area, with a sunken track and a raised thumb
     centered in it. */
  .root {
    --slider-h: var(--ui-control-sm);
    --slider-track-h: 6px;
    --slider-knob-h: 20px;
    /* A capsule, like every pressable thing: wider than tall. */
    --slider-knob-w: calc(var(--slider-knob-h) * var(--ui-capsule));
    --slider-fraction: 0;
    /* The switch's thumb: the raised surface in light, a light gray in dark,
       where a knob the color of the surface would read as a hole. */
    --slider-knob: light-dark(var(--ui-surface), color-mix(in oklch, var(--ui-foreground) 86%, var(--ui-surface)));
    --slider-range: var(--ui-accent);
    display: grid;
    min-width: 0;
    font-family: var(--ui-font-sans);
    -webkit-tap-highlight-color: transparent;
  }

  .header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--ui-space-3);
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
    user-select: none;
  }

  .label {
    color: var(--ui-foreground);
    font-weight: var(--ui-weight-medium);
  }

  /* The longest value sits hidden in the same cell, so the readout never changes width. */
  .value {
    display: grid;
    flex-shrink: 0;
    justify-items: end;
    color: var(--ui-muted);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    pointer-events: none;
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .sizer,
  .shown {
    grid-area: 1 / 1;
  }

  .sizer {
    visibility: hidden;
  }

  /* Base UI's Slider.Control: a press anywhere on the row sets the value, a drag follows. */
  .control {
    position: relative;
    height: var(--slider-h);
    cursor: pointer;
    touch-action: pan-y;
  }

  @media (pointer: coarse) {
    .control::after {
      content: "";
      position: absolute;
      inset: calc((var(--slider-h) - var(--ui-control-md)) / 2) 0;
    }
  }

  /* Holds the drawn parts. The thumb's layer slides past the end, so it's clipped,
     with room for the thumb to grow on press. */
  .rail {
    position: absolute;
    inset: 0;
    overflow: clip;
    overflow-clip-margin: var(--ui-space-1);
    pointer-events: none;
  }

  /* Sunken, like the segmented control's track: the faint fill and a hairline inner edge. */
  .track {
    position: absolute;
    top: 50%;
    inset-inline: 0;
    height: var(--slider-track-h);
    margin-top: calc(var(--slider-track-h) / -2);
    overflow: clip;
    border-radius: var(--ui-radius-full);
    background: var(--ui-fill);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border-strong);
    pointer-events: none;
  }

  /* The full track, slid back so its end sits under the thumb's center. */
  .range {
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: var(--slider-range);
    translate: calc((var(--slider-fraction) - 1) * (100% - var(--slider-knob-w)) - var(--slider-knob-w) / 2) 0;
    transition:
      translate var(--ui-dur-glide) var(--ui-ease-glide),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  :is([dir="rtl"]) .root .range {
    translate: calc((1 - var(--slider-fraction)) * (100% - var(--slider-knob-w)) + var(--slider-knob-w) / 2) 0;
  }

  /* A full-width layer slid by the value, so the thumb moves on the compositor. */
  .knobLayer {
    position: absolute;
    inset: 0;
    translate: calc(var(--slider-fraction) * (100% - var(--slider-knob-w))) 0;
    pointer-events: none;
    transition: translate var(--ui-dur-glide) var(--ui-ease-glide);
  }

  :is([dir="rtl"]) .root .knobLayer {
    translate: calc(var(--slider-fraction) * (var(--slider-knob-w) - 100%)) 0;
  }

  /* Raised, like the segmented control's pill: surface, a firm hairline, a hint of lift. */
  .knob {
    position: absolute;
    top: 50%;
    inset-inline-start: 0;
    width: var(--slider-knob-w);
    height: var(--slider-knob-h);
    margin-top: calc(var(--slider-knob-h) / -2);
    border-radius: var(--ui-radius-full);
    background: var(--slider-knob);
    box-shadow:
      0 0 0 var(--ui-hairline) var(--ui-border-strong),
      var(--ui-shadow-control);
    /* Drives the focus ring: dark on the knob in both themes. */
    color: light-dark(var(--ui-foreground), var(--ui-surface));
    transition:
      scale var(--ui-dur-snap) var(--ui-ease-snap),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* A drag or a held key: the thumb and range sit under the input, no easing. */
  .root[data-follow] :is(.range, .knobLayer) {
    transition: none;
  }

  /* Base UI's track and thumb lie over the drawn ones and draw nothing. */
  .hitTrack {
    height: 100%;
  }

  /* The thumb holds the focusable range input; as wide as the drawn thumb, so their centers match. */
  .thumb {
    top: 50%;
    width: var(--slider-knob-w);
    height: 100%;
    outline: none;
  }

  @media (hover: hover) {
    .root:not([data-disabled]) .control:hover {
      --slider-knob: light-dark(
        var(--ui-fill-solid),
        color-mix(in oklch, var(--ui-foreground) 92%, var(--ui-surface))
      );
    }
  }

  /* Calm press: the thumb grows a touch at once and springs back on release. */
  .root:not([data-disabled]) .control:active .knob {
    scale: 1.08;
    transition-duration: var(--ui-dur-press), var(--ui-dur-instant);
  }

  .root:has(.thumb :focus-visible) .knob {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .root:has(.thumb :focus-visible) .value,
  .root[data-follow] .value {
    color: var(--ui-foreground);
  }

  /* One layer at half opacity, so the thumb, range and track dim together without seams. */
  .root[data-disabled] {
    opacity: 0.5;
  }

  .root[data-disabled] .control {
    cursor: default;
  }

  @media (prefers-reduced-motion: reduce) {
    .range {
      transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
    }
    .knobLayer {
      transition: none;
    }
    .knob {
      transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
    }
    .root:not([data-disabled]) .control:active .knob {
      scale: none;
    }
  }
}

"use client";

import { useLayoutEffect, useMemo, useRef, useState, type CSSProperties } from "react";
import { Slider as BaseSlider } from "@base-ui/react/slider";
import { TextMorph } from "../text-morph/text-morph";
import styles from "./slider.module.css";

type SliderProps = {
  label: string;
  min?: number;
  max?: number;
  step?: number;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  /** The value as shown at the end of the label row. */
  format?: (value: number) => string;
  /** The value as read by screen readers. Defaults to `format`. */
  valueText?: (value: number) => string;
  /** Morph the shown value from one to the next. Turn off for wide ranges dragged fast. */
  morph?: boolean;
  name?: string;
  disabled?: boolean;
  className?: string;
};

/** At most this many values are formatted to find the widest readout. */
const MAX_SAMPLES = 500;

/** A press that wanders less than this is still a click on the track, and glides. */
const DRAG_SLOP = 3;

/** A sunken track with a raised thumb, Base UI's Slider underneath for all input and assistive tech. */
export function Slider({
  label,
  min = 0,
  max = 100,
  step = 1,
  value: controlled,
  defaultValue,
  onValueChange,
  format = String,
  valueText,
  morph = true,
  name,
  disabled,
  className,
}: SliderProps) {
  const [uncontrolled, setUncontrolled] = useState(() => clamp(defaultValue ?? min, min, max));
  const value = controlled !== undefined ? clamp(controlled, min, max) : uncontrolled;
  const fraction = max > min ? (value - min) / (max - min) : 0;
  const steps = step > 0 ? Math.round((max - min) / step) : 0;
  const shown = format(value);
  // A drag or a held arrow key follows the input 1:1, without gliding or morphing.
  // A click on the track, a slightly wobbly one included, and a single key press glide.
  // (Base UI's own data-dragging is on from pointerdown, so it can't tell a click from a drag.)
  const [following, setFollowing] = useState(false);
  const pressRef = useRef<{ x: number; y: number } | null>(null);

  // The readout holds the width of its widest value, so dragging never moves the label.
  // Callers pass `format` inline, so the list is rebuilt only when the range or what it shows changes.
  const formatKey = `${format(min)}\n${format(max)}\n${format(min + step)}`;
  const candidates = useMemo(
    () => {
      const count = Math.min(steps, MAX_SAMPLES);
      const texts = new Set<string>();
      for (let i = 0; i <= count; i++) {
        const raw = count ? min + ((max - min) * i) / count : min;
        texts.add(format(step > 0 ? clamp(min + Math.round((raw - min) / step) * step, min, max) : raw));
      }
      // A string a character shorter can still be wider; any shorter can't.
      const longest = Math.max(...Array.from(texts, (t) => t.length));
      return Array.from(texts).filter((t) => t.length >= longest - 1);
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [min, max, step, steps, formatKey],
  );
  const [widest, setWidest] = useState(() => candidates.reduce((a, b) => (b.length > a.length ? b : a)));
  const valueRef = useRef<HTMLSpanElement>(null);

  // Not every font has tabular figures, so measure the candidates in the readout's own font.
  useLayoutEffect(() => {
    const host = valueRef.current;
    if (!host) return;
    const measure = () => {
      const probe = document.createElement("span");
      probe.style.cssText = "position:absolute;visibility:hidden;white-space:nowrap";
      host.appendChild(probe);
      let best = candidates[0];
      let bestWidth = -1;
      for (const text of candidates) {
        probe.textContent = text;
        const width = probe.getBoundingClientRect().width;
        if (width > bestWidth) [best, bestWidth] = [text, width];
      }
      probe.remove();
      setWidest(best);
    };
    measure();
    let live = true;
    document.fonts?.ready.then(() => live && measure());
    return () => {
      live = false;
    };
  }, [candidates]);

  function set(next: number) {
    if (next === value) return;
    if (controlled === undefined) setUncontrolled(next);
    onValueChange?.(next);
  }

  return (
    <BaseSlider.Root
      className={className ? `${styles.root} ${className}` : styles.root}
      value={value}
      min={min}
      max={max}
      step={step}
      largeStep={step * 10}
      name={name}
      disabled={disabled}
      // Keeps the thumb inside the track, so a press lands where the drawn thumb goes.
      thumbAlignment="edge"
      onValueChange={(next, details) => {
        const event = details.event;
        if (details.reason === "drag" && !following) {
          const press = pressRef.current;
          const at = pointOf(event);
          if (!press || !at || Math.hypot(at.x - press.x, at.y - press.y) >= DRAG_SLOP) setFollowing(true);
        } else if (details.reason === "keyboard") {
          setFollowing(event instanceof KeyboardEvent && event.repeat);
        }
        set(Array.isArray(next) ? next[0] : next);
      }}
      // A key commits on every press, so a held key is let go of on keyup instead.
      onValueCommitted={(_, details) => {
        if (details.reason !== "keyboard") setFollowing(false);
      }}
      onKeyUp={() => setFollowing(false)}
      onBlur={() => setFollowing(false)}
      data-follow={following || undefined}
      style={{ "--slider-fraction": fraction } as CSSProperties}
    >
      <div className={styles.header}>
        <BaseSlider.Label className={styles.label}>{label}</BaseSlider.Label>
        <span ref={valueRef} className={styles.value} aria-hidden="true">
          <span className={styles.sizer}>{widest}</span>
          <span className={styles.shown}>{morph && !following ? <TextMorph>{shown}</TextMorph> : shown}</span>
        </span>
      </div>
      <BaseSlider.Control
        className={styles.control}
        onPointerDown={(event) => {
          pressRef.current = { x: event.clientX, y: event.clientY };
          setFollowing(false);
        }}
      >
        <span className={styles.rail} aria-hidden="true">
          <span className={styles.track}>
            <span className={styles.range} />
          </span>
          <span className={styles.knobLayer}>
            <span className={styles.knob} />
          </span>
        </span>
        <BaseSlider.Track className={styles.hitTrack}>
          <BaseSlider.Thumb className={styles.thumb} getAriaValueText={(_, v) => (valueText ?? format)(v)} />
        </BaseSlider.Track>
      </BaseSlider.Control>
    </BaseSlider.Root>
  );
}

function pointOf(event: Event) {
  if ("clientX" in event && typeof event.clientX === "number") {
    return { x: event.clientX, y: (event as MouseEvent).clientY };
  }
  const touch = "changedTouches" in event ? (event as TouchEvent).changedTouches[0] : undefined;
  return touch ? { x: touch.clientX, y: touch.clientY } : null;
}

function clamp(n: number, min: number, max: number) {
  return Math.min(max, Math.max(min, n));
}
